import{_ as t,o as e,c as n,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"16. Att förändra databasens struktur","description":"","frontmatter":{},"headers":[],"relativePath":"sv/chapters/16-att-forandra-databasens-struktur.md","filePath":"sv/chapters/16-att-forandra-databasens-struktur.md"}'),s={name:"sv/chapters/16-att-forandra-databasens-struktur.md"};function r(l,a,d,k,o,p){return e(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="_16-att-forandra-databasens-struktur" tabindex="-1">16. Att förändra databasens struktur <a class="header-anchor" href="#_16-att-forandra-databasens-struktur" aria-label="Permalink to &quot;16. Att förändra databasens struktur&quot;">​</a></h1><p>När vi först skapade bokhandelns databas bestämde vi vilka uppgifter en produkt, kund och författare skulle ha.</p><p>Men verksamheten står inte stilla. Vi kanske upptäcker att vi behöver spara ISBN för böcker, skilja mellan produkter som är aktiva och inaktiva eller registrera fler leveransuppgifter.</p><p>Då räcker det inte att lägga till eller ändra rader med <code>INSERT</code> och <code>UPDATE</code>. Vi behöver förändra <strong>själva strukturen</strong> för den information vi kan lagra.</p><p>En datamodell är alltså inte något vi konstruerar en gång för alla. Den behöver kunna utvecklas utan att vi förlorar information eller gör befintliga system obrukbara.</p><h2 id="grund" tabindex="-1">Grund <a class="header-anchor" href="#grund" aria-label="Permalink to &quot;Grund&quot;">​</a></h2><h3 id="att-forandra-data-eller-att-forandra-strukturen" tabindex="-1">Att förändra data eller att förändra strukturen <a class="header-anchor" href="#att-forandra-data-eller-att-forandra-strukturen" aria-label="Permalink to &quot;Att förändra data eller att förändra strukturen&quot;">​</a></h3><p>I förra kapitlet ändrade vi uppgifter med exempelvis:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> price </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 225</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">00</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Det förändrar värdet i en befintlig kolumn.</p><p>Men om vi vill börja lagra ISBN för våra böcker behöver vi en <strong>ny kolumn</strong>. Då använder vi <code>ALTER TABLE</code>.</p><h3 id="att-lagga-till-en-kolumn" tabindex="-1">Att lägga till en kolumn <a class="header-anchor" href="#att-lagga-till-en-kolumn" aria-label="Permalink to &quot;Att lägga till en kolumn&quot;">​</a></h3><p>Anta att vår tabell <code>products</code> innehåller:</p><table tabindex="0"><thead><tr><th>id</th><th>title</th><th style="text-align:right;">price</th><th style="text-align:right;">stock</th></tr></thead><tbody><tr><td>1</td><td>Vägen hem</td><td style="text-align:right;">200.00</td><td style="text-align:right;">12</td></tr><tr><td>2</td><td>Den blå staden</td><td style="text-align:right;">150.00</td><td style="text-align:right;">0</td></tr><tr><td>3</td><td>Vinterljus</td><td style="text-align:right;">249.00</td><td style="text-align:right;">4</td></tr></tbody></table><p>Vi vill börja registrera ISBN:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ADD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COLUMN isbn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">VARCHAR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Kolumnen finns nu i tabellen, även för produkter vi redan registrerat.</p><table tabindex="0"><thead><tr><th>id</th><th>title</th><th>isbn</th></tr></thead><tbody><tr><td>1</td><td>Vägen hem</td><td>NULL</td></tr><tr><td>2</td><td>Den blå staden</td><td>NULL</td></tr><tr><td>3</td><td>Vinterljus</td><td>NULL</td></tr></tbody></table><p>Vi har inte förlorat de gamla raderna. Men databasen känner ännu inte till deras ISBN.</p><p>Det illustrerar skillnaden mellan att <strong>göra plats för en uppgift</strong> och att <strong>faktiskt känna till dess värde</strong>.</p><h3 id="att-fylla-i-informationen" tabindex="-1">Att fylla i informationen <a class="header-anchor" href="#att-fylla-i-informationen" aria-label="Permalink to &quot;Att fylla i informationen&quot;">​</a></h3><p>När vi har kontrollerat vilka ISBN som hör till vilka produkter kan vi lägga till dem med <code>UPDATE</code>:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> isbn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;9781234567897&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>ISBN är här ett illustrativt värde. Vi använder text eftersom ett ISBN är en identifierare, inte en kvantitet som vi ska räkna med.</p><p>När en ny kolumn införs kan vi alltså behöva kombinera två olika slags förändringar:</p><ol><li>Ändra <strong>strukturen</strong> med <code>ALTER TABLE</code>.</li><li>Ändra <strong>innehållet</strong> med <code>UPDATE</code>.</li></ol><h3 id="att-lagga-till-ett-standardvarde" tabindex="-1">Att lägga till ett standardvärde <a class="header-anchor" href="#att-lagga-till-ett-standardvarde" aria-label="Permalink to &quot;Att lägga till ett standardvärde&quot;">​</a></h3><p>Anta att vi vill markera om produkter ingår i det aktiva sortimentet.</p><p>Vi kan lägga till en kolumn med ett förvalt värde:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ADD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COLUMN is_active </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BOOLEAN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TRUE;</span></span></code></pre></div><p>Tanken är att våra befintliga produkter ska betraktas som aktiva tills vi bestämmer något annat.</p><p>Vi behöver då fundera över om det är en rimlig regel för <strong>alla redan registrerade produkter</strong>, inte bara för nya produkter.</p><p>Olika databassystem kan hantera tillägg av kolumner, standardvärden och befintliga rader på olika sätt, särskilt när tabellerna är stora.[^add-column]</p><p>[^add-column]: Syntaxen <code>ADD COLUMN</code> stöds brett, men detaljer och möjligheterna att lägga till <code>NOT NULL</code>, standardvärden eller vissa begränsningar skiljer sig mellan MySQL, PostgreSQL, SQLite och SQL Server.</p><h3 id="att-andra-en-kolumns-definition" tabindex="-1">Att ändra en kolumns definition <a class="header-anchor" href="#att-andra-en-kolumns-definition" aria-label="Permalink to &quot;Att ändra en kolumns definition&quot;">​</a></h3><p>Ibland behöver vi ändra en datatyp eller tillåta längre värden.</p><p>Om <code>title</code> från början definierats som <code>VARCHAR(100)</code> kanske det inte räcker för alla boktitlar.</p><p>I MySQL kan vi exempelvis skriva:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">MODIFY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COLUMN title </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">VARCHAR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">NOT NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Detta förändrar kolumnens definition, inte dess namn eller vilket slags uppgift den beskriver.</p><p>Syntaxen varierar mellan olika SQL-dialekter.[^alter-type]</p><p>[^alter-type]: PostgreSQL använder exempelvis <code>ALTER COLUMN ... TYPE</code>. SQL Server använder <code>ALTER COLUMN</code> med en datatypsdefinition, medan SQLite har mer begränsade möjligheter att ändra befintliga kolumner direkt. MySQL-exemplet ovan använder <code>MODIFY COLUMN</code>.</p><h3 id="att-ta-bort-en-kolumn" tabindex="-1">Att ta bort en kolumn <a class="header-anchor" href="#att-ta-bort-en-kolumn" aria-label="Permalink to &quot;Att ta bort en kolumn&quot;">​</a></h3><p>Om vi inte längre behöver ett attribut kan vi ta bort dess kolumn:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DROP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COLUMN isbn;</span></span></code></pre></div><p>Men då försvinner också de lagrade ISBN-värdena ur tabellen.</p><p>Det är därför en strukturell förändring kan vara mer omfattande än den ser ut. Vi förändrar inte bara vilka frågor vi kan ställa i framtiden; vi kan också ta bort information som redan finns.</p><p>Detta är ett <strong>alternativt exempel</strong>, inte något vi bör göra direkt efter att ha infört ISBN.</p><h3 id="att-byta-namn-pa-en-kolumn" tabindex="-1">Att byta namn på en kolumn <a class="header-anchor" href="#att-byta-namn-pa-en-kolumn" aria-label="Permalink to &quot;Att byta namn på en kolumn&quot;">​</a></h3><p>Vi kan också vilja byta namn på en kolumn, exempelvis från <code>title</code> till <code>product_title</code>:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RENAME COLUMN title </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> product_title;</span></span></code></pre></div><p>Många moderna databassystem stöder denna syntax, men äldre versioner och vissa dialekter använder andra konstruktioner.[^rename]</p><p>[^rename]: Bland annat PostgreSQL, moderna MySQL-versioner och SQLite stöder <code>RENAME COLUMN</code>. SQL Server använder i regel <code>sp_rename</code> för att byta namn på en kolumn.</p><p>En namnändring kan påverka alla SQL-frågor och program som använder det gamla namnet.</p><h2 id="avancerat" tabindex="-1">Avancerat <a class="header-anchor" href="#avancerat" aria-label="Permalink to &quot;Avancerat&quot;">​</a></h2><h3 id="vad-ar-en-databasmigration" tabindex="-1">Vad är en databasmigration? <a class="header-anchor" href="#vad-ar-en-databasmigration" aria-label="Permalink to &quot;Vad är en databasmigration?&quot;">​</a></h3><p>En <strong>migration</strong> är en kontrollerad förändring av databasens struktur och ibland även dess data.</p><p>Vi kan beskriva förändringen i en SQL-fil:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 001_add_isbn.sql</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ADD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COLUMN isbn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">VARCHAR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Nästa ändring kan finnas i en annan fil:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 002_add_is_active.sql</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ALTER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ADD</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> COLUMN is_active </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BOOLEAN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NOT NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DEFAULT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TRUE;</span></span></code></pre></div><p>Filerna dokumenterar hur databasen har utvecklats. Ett migrationsverktyg kan hålla reda på vilka ändringar som redan genomförts.</p><p>Migrationsskript bör normalt versionshanteras tillsammans med den kod och dokumentation som är beroende av databasens struktur.</p><h3 id="utoka-overfor-begransa" tabindex="-1">Utöka, överför, begränsa <a class="header-anchor" href="#utoka-overfor-begransa" aria-label="Permalink to &quot;Utöka, överför, begränsa&quot;">​</a></h3><p>Att göra en stor förändring direkt kan vara riskabelt om flera applikationer använder databasen.</p><p>En vanlig strategi är att ändra modellen i flera mindre steg:</p><p><strong>1. Utöka.</strong> Lägg till en ny kolumn utan att omedelbart ta bort den gamla.</p><p><strong>2. Överför.</strong> Fyll den nya kolumnen med kontrollerad information och uppdatera programmen så att de använder den.</p><p><strong>3. Begränsa.</strong> När vi vet att den nya strukturen fungerar kan vi införa striktare regler och så småningom ta bort det gamla.</p><p>Detta brukar kallas <em>expand and contract</em>.</p><p>Strategin gör det möjligt att låta äldre och nyare programversioner fungera under en övergångsperiod, om förändringen planeras för det.</p><h3 id="att-lagga-till-en-regel-pa-befintliga-data" tabindex="-1">Att lägga till en regel på befintliga data <a class="header-anchor" href="#att-lagga-till-en-regel-pa-befintliga-data" aria-label="Permalink to &quot;Att lägga till en regel på befintliga data&quot;">​</a></h3><p>Anta att vi vill kräva att varje bok har ett ISBN.</p><p>Det är inte tillräckligt att direkt lägga till <code>NOT NULL</code> om tabellen redan innehåller produkter där ISBN saknas.</p><p>Vi kan behöva:</p><ul><li>Först lägga till kolumnen utan kravet.</li><li>Ta reda på vilka värden som saknas och fylla i dem.</li><li>Kontrollera att informationen är tillräckligt korrekt.</li><li>Först därefter göra kolumnen obligatorisk, om den verkligen ska gälla för alla produkter.</li></ul><p>Och innan vi gör detta behöver vi kanske fråga oss om <strong>alla produkter är böcker</strong>. Om vår bokhandel senare säljer vykort eller presentartiklar kan ett obligatoriskt ISBN på tabellen <code>products</code> vara fel modellering.</p><p>En strukturell förändring kan alltså avslöja att vi behöver tänka om kring datamodellen.</p><h3 id="att-andra-en-relation" tabindex="-1">Att ändra en relation <a class="header-anchor" href="#att-andra-en-relation" aria-label="Permalink to &quot;Att ändra en relation&quot;">​</a></h3><p>Anta att vi från början bestämt att varje produkt bara kan ha en författare, genom en kolumn <code>author_id</code> i <code>products</code>.</p><p>När vi senare behöver stöd för flera författare blir lösningen inte bara att öka utrymmet i en kolumn.</p><p>Vi behöver förändra <strong>relationen</strong> i modellen, exempelvis med kopplingstabellen <code>product_authors</code> som vi redan introducerat.</p><p>En sådan migration kan innebära att vi först skapar den nya tabellen, för över befintliga relationer, ändrar applikationens frågor och först därefter tar bort den gamla kolumnen.</p><p>Här ser vi skillnaden mellan att förändra en kolumns tekniska form och att förändra <strong>hur vi förstår informationens samband</strong>.</p><h3 id="gar-det-att-angra-en-migration" tabindex="-1">Går det att ångra en migration? <a class="header-anchor" href="#gar-det-att-angra-en-migration" aria-label="Permalink to &quot;Går det att ångra en migration?&quot;">​</a></h3><p>Vissa databasändringar kan ångras med en omvänd SQL-instruktion. Men det betyder inte att förlorad information automatiskt kommer tillbaka.</p><p>Om vi tar bort en kolumn som innehåller data kan det krävas en säkerhetskopia eller en separat överföring för att återställa värdena.</p><p>Det finns dessutom dialektskillnader i hur schemaändringar fungerar tillsammans med transaktioner. Exempelvis innebär många DDL-operationer i MySQL implicita commits, medan PostgreSQL ofta kan hantera sådana ändringar transaktionellt.[^ddl]</p><p>[^ddl]: Exakt stöd för transaktionell DDL varierar mellan databassystem och mellan olika operationer. En rollback-strategi för en migration bör därför testas i den faktiska databasmiljön.</p><p>En genomtänkt migrationsplan omfattar därför både hur förändringen ska utföras och hur vi hanterar ett misslyckande.</p><h3 id="schemaforandringar-och-verksamhetens-tillganglighet" tabindex="-1">Schemaförändringar och verksamhetens tillgänglighet <a class="header-anchor" href="#schemaforandringar-och-verksamhetens-tillganglighet" aria-label="Permalink to &quot;Schemaförändringar och verksamhetens tillgänglighet&quot;">​</a></h3><p>På en liten övningsdatabas kan vi oftast ändra en tabell direkt.</p><p>I ett system med många användare och stora tabeller kan vissa schemaändringar ta tid, kräva låsning eller påverka pågående frågor och uppdateringar.</p><p>Därför behöver vi ibland planera förändringar för att undvika driftstopp, eller använda databasens särskilda möjligheter till mindre störande schemaändringar.</p><p>Det är ytterligare ett skäl att inte se <code>ALTER TABLE</code> som enbart ett sätt att redigera en tabellbeskrivning.</p><h3 id="en-view-kan-skydda-ett-granssnitt" tabindex="-1">En View kan skydda ett gränssnitt <a class="header-anchor" href="#en-view-kan-skydda-ett-granssnitt" aria-label="Permalink to &quot;En View kan skydda ett gränssnitt&quot;">​</a></h3><p>Föreställ dig att vi har en applikation som förväntar sig kolumnen <code>title</code>, men att vi vill byta namn på den i vår lagringsmodell.</p><p>En möjlig strategi är att erbjuda ett fortsatt stabilt gränssnitt med en <strong>View</strong>:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> VIEW</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> product_overview</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AS</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    id,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    product_title </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> title,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    price</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products;</span></span></code></pre></div><p>Här antar vi att den underliggande kolumnen redan heter <code>product_title</code>.</p><p>Program som frågar vyn <code>product_overview</code> kan då fortfarande få en kolumn med namnet <code>title</code>.</p><p>Detta är bara ett exempel på hur en View kan användas för att skilja den <strong>interna lagringsmodellen</strong> från det <strong>gränssnitt andra system använder</strong>. Det kan fortfarande krävas planering av beroenden och rättigheter.</p><p>Vi fördjupar oss i Views i nästa kapitel.</p><h3 id="att-forandra-en-modell-ar-ocksa-att-forandra-ett-avtal" tabindex="-1">Att förändra en modell är också att förändra ett avtal <a class="header-anchor" href="#att-forandra-en-modell-ar-ocksa-att-forandra-ett-avtal" aria-label="Permalink to &quot;Att förändra en modell är också att förändra ett avtal&quot;">​</a></h3><p>När vi lägger till ett attribut utökar vi vad databasen kan säga om verkligheten.</p><p>När vi tar bort en kolumn upphör databasen kanske att kunna beskriva ett tidigare sakförhållande.</p><p>Och när vi förändrar relationerna mellan tabellerna kan vi förändra vilka kombinationer av information systemet betraktar som giltiga.</p><p>En databasstruktur är därför inte bara en teknisk ritning. Den fungerar också som ett <strong>avtal om informationens betydelse</strong>, mellan verksamheten, databasen och de program som använder den.</p><h2 id="reflektion" tabindex="-1">Reflektion <a class="header-anchor" href="#reflektion" aria-label="Permalink to &quot;Reflektion&quot;">​</a></h2><ol><li>Vad är skillnaden mellan att lägga till en ny kolumn och att faktiskt känna till värdena som ska stå i den?</li><li>Varför kan det vara säkrare att först utöka en databasmodell och senare ta bort äldre delar, i stället för att ändra allt på en gång?</li><li>När vi ändrar en tabell, förändrar vi då bara dess tekniska struktur – eller ibland också vårt sätt att förstå verksamheten?</li></ol>`,110)])])}const c=t(s,[["render",r]]);export{g as __pageData,c as default};
